function ExperimentWorkflow({ site, onSaved }: {
    site: Site;
    onSaved: () => void;
}) {
    const [error, setError] = useState('');
    const [result, setResult] = useState<Row>();
    return <section className="panel"><h2>{t("实验创建与归因接入")}</h2><p>{t("需要标准标识、访客同意和实验开关。按稳定标识分配。转化来自采集到的目标事件。")}</p><form onSubmit={async (e) => { e.preventDefault(); const f = new FormData(e.currentTarget); try {
        setResult(await api<Row>(`/api/v1/sites/${site.id}/experiments`, { name: f.get('name'), variants: String(f.get('variants')).split('\n').map(s => s.trim()).filter(Boolean), goal: f.get('goal') }));
        onSaved();
    }
    catch (err) {
        setError((err as Error).message);
    } }}><label>{t("实验名称")}<input name="name" required/></label><label>{t("变体名称（每行一个，至少两个）")}<textarea name="variants" required placeholder="control\nvariant-b"/></label><label>{t("转化事件名称")}<input name="goal" required placeholder="signup"/></label><button>{t("创建实验")}</button></form>{result && <><h3>{t("宿主网站接入")}</h3><pre>{`// ${t('只在访客同意后调用。visitor_id 来自第一方 _baize_uid')}
fetch('${location.origin}/api/v1/experiments/${result.id}/assign', {
  method: 'POST', headers: {'Content-Type': 'application/json'},
  body: JSON.stringify({site_id:'${site.id}', visitor_id:uid, consent:true})
}).then(r => r.json()).then(({variant}) => applyVariant(variant));
// ${t('转化发生后：')}baize.track('${t('你的目标事件名')}');`}</pre></>}{error && <p role="alert" className="error">{error}</p>}</section>;
}
function QueryHealth({data}:{data:Row}){
 const en=language()==='en';
 if(data.watermark===undefined&&data.coverage===undefined)return null;
 const sessionUnavailable=typeof data.sessionMetricsStatus==='string'&&data.sessionMetricsStatus.startsWith('unavailable');
 const complete=data.coverage===1;
 if(complete&&!sessionUnavailable)return null;
 const status=data.rangeStatus==='future_only'?(en?'This date range is in the future.':'所选日期尚未到来。'):data.rangeStatus==='partial_unavailable'?(en?'Some dates are outside the available data range.':'部分日期超出可用数据范围。'):sessionUnavailable?(en?'Some session metrics are unavailable for this period.':'此时段的部分会话指标不可用。'):(en?'Data for this period is incomplete.':'此时段数据尚未完整。');
 return <section className="notice customer-data-status" aria-label={en?'Data status':'数据状态'} role="status"><span>{status}</span>{Array.isArray(data.limitations)&&data.limitations.length>0&&<details><summary>{en?'Details':'查看详情'}</summary><ul>{data.limitations.map((value,index)=><li key={index}>{String(value)}</li>)}</ul></details>}</section>;
}
function factInsight(data:Row){const pv=Number((data.totals as Row)?.pv||0);const sources=rows(data.sources).sort((a,b)=>Number(b.pv)-Number(a.pv));if(!pv||!sources[0])return t('所选期间暂无已聚合的页面浏览。');const source=sources[0];return `${t('所选期间页面浏览')} ${pv} · ${t('首位来源')} ${String(source.channel)}: ${Number(source.pv)} (${(Number(source.pv)/pv*100).toFixed(1)}%)`;}
