function PageDetail({siteId,pages,query}:{siteId:string;pages:Row[];query:string}){const [path,setPath]=useState('');const [data,setData]=useState<Row>();const [error,setError]=useState('');const chosen=path||String(pages[0]?.path||'');useEffect(()=>{const controller=new AbortController();let active=true;setData(undefined);setError('');const params=new URLSearchParams(query);params.set('path',chosen);if(chosen)void api<Row>(`/api/v1/sites/${siteId}/pages/detail?${params}`,undefined,'GET',controller.signal).then(result=>{if(active)setData(result);}).catch(e=>{if(active)setError(e.message);});return()=>{active=false;controller.abort();};},[siteId,chosen,query]);return <section className="panel"><h2>{t("单页面详情")}</h2><label>{t("选择已采集页面")}<select value={chosen} onChange={e=>setPath(e.target.value)}>{pages.map(p=><option key={String(p.path)}>{String(p.path)}</option>)}</select></label>{error&&<p role="alert" className="error">{error}</p>}{data&&<><p>{t("筛选用还在保留期内的事件。水位")}{readable(data.watermark)}{t("· 覆盖率")}{typeof data.coverage==='number'?(data.coverage*100).toFixed(0):'—'}{language()==='en'?'%. Sessions use the first pageview landing page; goals use their completion event and last-click attribution.':'%。会话按首次 pageview 落地页计；目标按完成事件及 last-click 归因。'}</p><Chart data={rows(data.trend)}/><h3>{t("页面来源")}</h3><Table data={rows(data.sources)}/>{Object.entries((data.audience||{}) as Row).map(([dimension,values])=><section className="dim-card" key={dimension}><h3>{ownValue(labels,dimension)||dimension}</h3><Table data={Object.entries(values as Row).map(([value,count])=>({[dimension]:value,count}))}/></section>)}</>}</section>;}
