type Field = [
    string,
    string,
    string?
];
function Action({ title, endpoint, method = 'POST', fields, onSaved, scopeLabel, currentRetention }: {
    title: string;scopeLabel?:string;currentRetention?:number;
    endpoint: string;
    method?: string;
    fields: Field[];
    onSaved: () => void;
}) { const [result, setResult] = useState<Row>(); const [error, setError] = useState(''); const [busy, setBusy] = useState(false); return <section className="panel settings-panel"><h2>{t(title)}</h2><form className="settings-form" onSubmit={async (e) => { e.preventDefault();if(busy)return;const input=new FormData(e.currentTarget);if(endpoint.endsWith('/delete-visitor')&&!window.confirm(`${t('此操作永久删除所指定访客的明细并阻止重建。确认继续？')}\n${scopeLabel||''}\n${['visitor_id','user_id'].flatMap(key=>input.get(key)?[`${key}: ${String(input.get(key))}`]:[]).join('\n')||'—'}`))return;if(endpoint.endsWith('/retention')&&currentRetention!==undefined&&Number(input.get('days'))<currentRetention&&!window.confirm(`${language()==='en'?'Shortening retention can permanently remove older detail. Continue?':'缩短保留期可能永久删除较旧明细，确认继续？'}\n${scopeLabel||''}\n${currentRetention} → ${String(input.get('days'))} ${language()==='en'?'days':'天'}`))return; setBusy(true); setError(''); try {
    const f = Object.fromEntries(new FormData(e.currentTarget));
    const payload: Row = {};
    for (const [name, , type] of fields) {
        const value = f[name];
        if (value === '')
            continue;
        payload[name] = type === 'json' ? JSON.parse(String(value)) : type === 'number' ? Number(value) : type === 'datetime-local' ? new Date(String(value)).toISOString() : value;
    }
    setResult(await api<Row>(endpoint, payload, method));
    onSaved();
}
catch (err) {
    setError((err as Error).message);
}
finally {
    setBusy(false);
} }}>{fields.map(([name, label, type]) => <label key={name}>{t(label)}{type === 'json' ? <textarea name={name} placeholder="{}" spellCheck={false}/> : <input name={name} type={type || 'text'} defaultValue={name==='days'?currentRetention:undefined}/>}</label>)}<button disabled={busy}>{busy ? t('正在提交…') : t(title)}</button></form>{error && <p className="error" role="alert">{error}</p>}{result && <p role="status" className="settings-feedback">{language()==='en'?'Saved':'已保存'}</p>}</section>; }
